{"path": "src/models/customer.js", "content": "const mongoose = require('mongoose');
const { Schema } = mongoose;

const SourceSchema = new Schema({}, { strict: false });

const CustomerSchema = new Schema({
  customerId: { type: String, required: true, index: true },
  sources: {
    crm: { type: SourceSchema, default: {} },
    ecommerce: { type: SourceSchema, default: {} },
    support: { type: SourceSchema, default: {} }
  },
  createdAt: { type: Date, default: () => new Date() },
  updatedAt: { type: Date, default: () => new Date() }
});

// Ensure a unique index on customerId (seed script will call createIndexes as well)
CustomerSchema.index({ customerId: 1 }, { unique: true });

function createModel(db) {
  // db is a mongoose.Connection returned by connection.useDb
  return db.model('Customer', CustomerSchema);
}

module.exports = { createModel };
"}

{"path": "src/lib/upsert.js", "content": "const { createModel } = require('../models/customer');

async function upsertEvent(db, event) {
  // event: { source, customerId, attributes }
  const Customer = createModel(db);
  const { source, customerId, attributes } = event;
  if (!source || !customerId || typeof attributes !== 'object') {
    throw new Error('Invalid event shape; require source, customerId, attributes');
  }

  const filter = { customerId };
  const setPath = `sources.${source}`;
  const update = {
    $set: {
      [setPath]: attributes,
      updatedAt: new Date()
    },
    $setOnInsert: {
      customerId,
      createdAt: new Date()
    }
  };
  const opts = { upsert: true };

  const res = await Customer.updateOne(filter, update, opts);
  return res;
}

module.exports = { upsertEvent };
"}

{"path": "src/routes/events.js", "content": "const express = require('express');
const router = express.Router();
const dbModule = require('../db');
const { upsertEvent } = require('../lib/upsert');

router.post('/', async (req, res) => {
  try {
    const { source, customerId, attributes } = req.body;
    if (!source || !customerId || !attributes) {
      return res.status(400).json({ error: 'Missing required fields: source, customerId, attributes' });
    }
    const db = await dbModule.connect();
    const result = await upsertEvent(db, { source, customerId, attributes });
    return res.json({ ok: true, result });
  } catch (err) {
    console.error('Error in /events:', err.message);
    return res.status(500).json({ error: err.message });
  }
});

module.exports = router;
"}

{"path": "src/index.js", "content": "const express = require('express');
require('dotenv').config();
const eventsRoute = require('./routes/events');
const dbModule = require('./db');

const app = express();
app.use(express.json());

app.use('/events', eventsRoute);

const PORT = process.env.PORT || 3000;

async function main() {
  await dbModule.connect();
  app.listen(PORT, () => {
    console.log(`Customer 360 sample listening on port ${PORT}`);
    console.log('POST events to /events with JSON { source, customerId, attributes }');
  });
}

main().catch(err => {
  console.error('Failed to start:', err.message);
  process.exit(1);
});
"}

{"path": "scripts/seed.js", "content": "const fs = require('fs');
const path = require('path');
const dbModule = require('../src/db');
const { createModel } = require('../src/models/customer');
const { upsertEvent } = require('../src/lib/upsert');

async function run() {
  const db = await dbModule.connect();
  const Customer = createModel(db);

  // Ensure indexes
  console.log('Ensuring indexes...');
  await Customer.createIndexes();

  const file = path.join(__dirname, '..', 'sample-data', 'events.json');
  const raw = fs.readFileSync(file, 'utf8');
  const events = JSON.parse(raw);

  for (const ev of events) {
    console.log('Upserting event:', ev.source, ev.customerId);
    await upsertEvent(db, ev);
  }

  console.log('Seed complete.');
  process.exit(0);
}

run().catch(err => {
  console.error('Seed failed:', err);
  process.exit(1);
});
"}

